# ============================================================================
# FAST-FAIL CIRCUIT BREAKER for Gemini (v66)
# Problem: when Gemini returns 429, every layer (fallback model, cache, multi-agent
# chain, 180s "rest") kept retrying one after another, so a single message took
# 1+ minute or never answered. Now: the first real 429 opens a short breaker for that
# (endpoint, search/plain) bucket; every further call to it fails INSTANTLY with a
# synthetic 429, so the existing fallbacks (Groq / web reader) run immediately.
# ============================================================================
import io as _io_cb
_GCB_LOCK = threading.Lock()
_GCB_OPEN = {}            # bucket -> (until_ts, reason)
_GCB_DEFAULT_SECS = int(os.environ.get("GEMINI_BREAKER_SECS", "20"))
_GCB_MAX_SECS = int(os.environ.get("GEMINI_BREAKER_MAX_SECS", "90"))
_orig_requests_post = requests.post

def _gcb_bucket(url, kw):
    path = url.split("?", 1)[0]
    body = kw.get("json") or {}
    grounded = bool(isinstance(body, dict) and body.get("tools"))
    return (path, grounded)

def _gcb_fake_429(wait):
    r = requests.models.Response()
    r.status_code = 429
    r.headers["Content-Type"] = "application/json"
    msg = json.dumps({"error": {"code": 429, "message": "local circuit breaker: Gemini recently returned 429",
                                "status": "RESOURCE_EXHAUSTED",
                                "details": [{"@type": "type.googleapis.com/google.rpc.RetryInfo", "retryDelay": f"{int(wait)}s"}]}}).encode()
    r._content = msg
    r.raw = _io_cb.BytesIO(msg)
    r.encoding = "utf-8"
    return r

def _gcb_post(url, *args, **kw):
    if not (isinstance(url, str) and "generativelanguage.googleapis.com" in url):
        return _orig_requests_post(url, *args, **kw)
    bucket = _gcb_bucket(url, kw)
    now = time.time()
    with _GCB_LOCK:
        st = _GCB_OPEN.get(bucket)
    if st and st[0] > now:
        return _gcb_fake_429(st[0] - now)
    resp = _orig_requests_post(url, *args, **kw)
    if resp.status_code == 429:
        secs = _GCB_DEFAULT_SECS
        try:
            txt = resp.text if not kw.get("stream") else ""
            m = re.search(r'"retryDelay"\s*:\s*"(\d+(?:\.\d+)?)s"', txt)
            if m:
                secs = int(float(m.group(1))) + 1
            if re.search(r"limit:\s*0\b", txt):
                secs = 1800           # this tier has no such quota at all (e.g. grounding on free tier)
            elif re.search(r"per\s?day|PerDay", txt, re.I):
                secs = 600
        except Exception:
            pass
        secs = min(max(secs, 5), 1800 if secs >= 600 else _GCB_MAX_SECS)
        with _GCB_LOCK:
            _GCB_OPEN[bucket] = (time.time() + secs, "429")
        print(f"[BREAKER] Gemini {bucket[0].rsplit('/',1)[-1][:60]} (search={bucket[1]}) paused {secs}s after 429 — callers fail fast")
    return resp

requests.post = _gcb_post
