def _curr_detail_spec(kind, detail, days):
    """detail ১–১০ → মডেলকে দেওয়া সংখ্যাগত নির্দেশ (কম = মোটা/সংক্ষিপ্ত, বেশি = অনেক ধাপ/বিস্তারিত)।
    [v28] ৫ = মাঝারি; ১০ = সবচেয়ে বিস্তারিত (এক ক্লাস প্রায় এক ঘণ্টার মতো ধাপ)। সময়ের কথা প্রম্পটে নেই —
    শুধু আইটেম/টপিক সংখ্যা।"""
    d = max(1, min(10, int(detail or 5)))
    if kind in ("course", "chapter"):
        items = {1: "3–4", 2: "4–5", 3: "5–6", 4: "6–8", 5: "8–10", 6: "10–12", 7: "12–15", 8: "15–18", 9: "18–22", 10: "22–28"}[d]
        topics = {1: "1–2", 2: "2–3", 3: "3–4", 4: "3–4", 5: "4–5", 6: "4–6", 7: "5–7", 8: "6–8", 9: "7–10", 10: "8–12"}[d]
        sentences = {1: "1", 2: "1–2", 3: "2", 4: "2–3", 5: "3–4", 6: "3–4", 7: "4–5", 8: "5–6", 9: "5–7", 10: "6–8"}[d]
        count_rule = (f"The whole plan is exactly {days} days — exactly {days} items, one per day." if days
                      else f"{items} items (according to the real scope of the topic; decide the number of days yourself).")
        label = 'brief, coarse steps' if d <= 3 else 'normal' if d <= 5 else 'many small steps, more detailed' if d <= 8 else 'extremely detailed — each part separately'
        return (f"{count_rule} Each item has {topics} topics and a description of {sentences} sentences. "
                f"Detail level {d}/10 ({label}).")
    sentences = {1: "half a line", 2: "1 line", 3: "1 line", 4: "1 line", 5: "1–2 lines",
                 6: "1–2 lines", 7: "2 lines", 8: "2–3 lines", 9: "3 lines", 10: "3–4 lines"}[d]
    return f"Give all the sectors (do not shorten the list); each summary {sentences}. Detail level {d}/10."


def _curr_clip(v, n):
    return re.sub(r"\s+", " ", str(v or "")).strip()[:n]


def _curr_sanitize(kind, parsed, query):
    """মডেলের JSON → নিরাপদ, সীমিত আকারের কাঠামো (ক্লায়েন্ট যেমন আছে তেমন দেখাবে/সেভ করবে)।"""
    if not isinstance(parsed, dict):
        return None
    out = {"kind": kind, "title": _curr_clip(parsed.get("title") or query, 100), "summary": _curr_clip(parsed.get("summary"), 300)}
    if kind in ("course", "chapter"):
        items = []
        for i, it in enumerate((parsed.get("items") or [])[:60]):
            if not isinstance(it, dict):
                continue
            title = _curr_clip(it.get("title"), 120)
            if not title:
                continue
            topics = [_curr_clip(t, 120) for t in (it.get("topics") or []) if _curr_clip(t, 120)][:12]
            try:
                day = int(it.get("day") or (i + 1))
            except (TypeError, ValueError):
                day = i + 1
            items.append({"day": day, "title": title, "description": _curr_clip(it.get("description"), 700), "topics": topics})
        if not items:
            return None
        out["items"] = items
    else:
        secs = []
        for sec in (parsed.get("sections") or [])[:80]:
            if isinstance(sec, dict) and _curr_clip(sec.get("title"), 120):
                secs.append({"title": _curr_clip(sec.get("title"), 120), "summary": _curr_clip(sec.get("summary"), 300)})
        if not secs:
            return None
        out["sections"] = secs
    return out


def _curr_json_call(prompt, system_prompt, user_key, user_groq_key):
    """কাঠামো-ধাপ: Gemini (JSON mode) → ব্যর্থ হলে Groq। (parsed_dict|None, tokens, provider, model)"""
    try:
        r = call_gemini(prompt, user_key=user_key, system_prompt=system_prompt, model=GEMINI_LEARNING_COMPOSE_MODEL,
                        generation_config={"responseMimeType": "application/json", "temperature": 0.3}, timeout=45)
        parsed = _robust_json_parse((r.get("text") or "").strip(), None)
        if isinstance(parsed, dict):
            return parsed, r.get("tokens", 0), "gemini", r.get("model") or GEMINI_LEARNING_COMPOSE_MODEL
    except AIProviderError as e:
        print(f"[CURRICULUM] gemini structure failed ({e}); trying groq")
    except Exception as e:
        print(f"[CURRICULUM] gemini structure error ({e}); trying groq")
    try:
        text, tokens, used = "", 0, None
        for piece, tok, used in stream_ai_raw([{"text": prompt}], system_prompt=system_prompt, model=None,
                                              user_key=user_groq_key, response_json_mode=True, provider="groq",
                                              temperature=0.3, fast=True):
            text += piece
            tokens = tok
        parsed = _robust_json_parse(text.strip(), None)
        if isinstance(parsed, dict):
            return parsed, tokens, "groq", used
    except Exception as e:
        print(f"[CURRICULUM] groq structure failed ({e})")
    return None, 0, None, None


