# ======================================================================
# LLM লগ (টেস্ট সিস্টেম) — চ্যাটের প্রোফাইল আইকন → "LLM লগ"
#
# প্রতিটা LLM কলে মডেলের কাছে হুবহু যা গেছে (system prompt + ইনপুট) আর হুবহু যা ফিরে এসেছে
# (আউটপুট) users/{uid}/llm_logs-এ রাখে। ডিফল্টে বন্ধ — ইউজার অ্যাপের ভিউয়ারের সুইচ দিয়ে নিজের
# জন্য চালু করে (users/{uid}.llm_trace_on)। বন্ধ থাকলে কলের পথে কোনো বাড়তি কাজ নেই (২০ সেকেন্ডে
# একবার ক্যাশ-করা ফ্ল্যাগ দেখা ছাড়া)।
#
# কোথায় ধরা হয়: সবচেয়ে নিচের স্তরে — stream_gemini_raw / stream_groq_raw / stream_groq_chat_raw /
# call_gemini / call_groq_chat / _supervisor_llm। গাইড মোডের সব কল (প্ল্যান, hop, repair, ELA 4N-এর
# দুই নির্বাচক, বিচারক, supervisor, router, চ্যাট রিপ্লাই) এগুলোর কোনো না কোনোটা দিয়ে যায়।
# API key কখনো লগে যায় না। ছবি যায় না — জায়গায় "[ছবি পাঠানো হয়েছে: ধরন, ~KB]" লেখা থাকে।
# ======================================================================
import inspect as _inspect

_LLMLOG_ENABLED_CACHE = {}      # uid -> (সময়, bool)
_LLMLOG_CACHE_TTL = 20          # সেকেন্ড
_LLMLOG_FIELD_CAP = 80_000      # প্রতি ক্ষেত্রে সর্বোচ্চ অক্ষর (Firestore ডকুমেন্ট ~1MiB সীমা)
_LLMLOG_KEEP = 300              # প্রতি ইউজারে সর্বোচ্চ এতগুলো রাখা হয়, পুরনোগুলো নিজে মুছে যায়


def _llmlog_col(uid):
    return get_db().collection("users").document(uid).collection("llm_logs")


def _llmlog_set_ctx(uid):
    """require_session থেকে ডাকা হয় — ইউজার, endpoint আর (থাকলে) সিস্টেম মোড মনে রাখে,
    যাতে পুল-থ্রেডে (ELA 4N-এর সমান্তরাল কল) চলা কলও ঠিক ইউজারের নামে লেখা হয়।"""
    system = None
    try:
        if request.is_json:
            body = request.get_json(silent=True)
            if isinstance(body, dict) and isinstance(body.get("system"), str):
                system = body.get("system")
    except Exception:
        pass
    try:
        _LLMLOG_CTX.set({"uid": uid, "path": request.path, "system": system})
    except Exception:
        pass


def _llmlog_who():
    ctx = _LLMLOG_CTX.get()
    if ctx and ctx.get("uid"):
        return ctx["uid"], ctx
    try:
        uid = g.get("uid")
    except RuntimeError:
        uid = None
    return (uid, {"uid": uid, "path": "", "system": None}) if uid else (None, None)


def _llmlog_enabled(uid, force=False):
    now = time.time()
    c = _LLMLOG_ENABLED_CACHE.get(uid)
    if c and not force and now - c[0] < _LLMLOG_CACHE_TTL:
        return c[1]
    on = False
    try:
        snap = get_db().collection("users").document(uid).get()
        on = bool((snap.to_dict() or {}).get("llm_trace_on"))
    except Exception as e:
        print(f"[WARN] llm-log flag read failed for uid={uid}: {e}")
    _LLMLOG_ENABLED_CACHE[uid] = (now, on)
    return on


def _llmlog_cut(s, cap=_LLMLOG_FIELD_CAP):
    s = s if isinstance(s, str) else ("" if s is None else str(s))
    if len(s) <= cap:
        return s
    return s[:cap] + f"\n…[truncated — kept the first {cap} of {len(s)} characters]"


def _llmlog_image_note(mime, b64):
    try:
        kb = max(1, int(len(b64 or "") * 3 / 4 / 1024))
    except Exception:
        kb = 0
    return f"[image sent: {mime or 'image'}, ~{kb} KB — image data is not kept in the log]"


def _llmlog_parts_text(parts):
    out = []
    for p in parts or []:
        if isinstance(p, dict):
            if p.get("text"):
                out.append(str(p["text"]))
            elif "inline_data" in p:
                d = p.get("inline_data") or {}
                out.append(_llmlog_image_note(d.get("mime_type"), d.get("data")))
            else:
                out.append(json.dumps(p, ensure_ascii=False)[:500])
        else:
            out.append(str(p))
    return "\n\n".join(out)


def _llmlog_begin(fn_name, provider):
    """None ফেরত মানে এই ইউজারের লগ বন্ধ (বা ইউজার অজানা) — কলার কিছুই করবে না।"""
    uid, ctx = _llmlog_who()
    if not uid or not _llmlog_enabled(uid):
        return None
    return {"uid": uid, "path": ctx.get("path") or "", "system": ctx.get("system") or "",
            "fn": fn_name, "provider": provider, "model": "", "system_prompt": "", "input": "",
            "extra": {}, "t0": time.time()}


def _llmlog_fill(rec, system, user_text, model, extra=None):
    rec["system_prompt"] = system if isinstance(system, str) else ("" if system is None else str(system))
    rec["input"] = user_text if isinstance(user_text, str) else ("" if user_text is None else str(user_text))
    rec["model"] = model or ""
    rec["extra"] = {k: v for k, v in (extra or {}).items() if v is not None}


def _llmlog_finish(rec, output, err=None, tokens=None, model=None, provider=None):
    if not rec:
        return
    try:
        out_s = output if isinstance(output, str) else ("" if output is None else str(output))
        sp, inp = rec["system_prompt"], rec["input"]
        cap = _LLMLOG_FIELD_CAP
        if sum(len(x.encode("utf-8")) for x in (sp, inp, out_s)) > 900_000:
            cap = 40_000   # বাংলা অক্ষর ৩ বাইট — মোট ডকুমেন্ট ১MiB-এর নিচে রাখতে
        doc = {
            "ts_ms": int(time.time() * 1000),
            "path": rec["path"], "system": rec["system"], "fn": rec["fn"],
            "provider": provider or rec["provider"], "model": model or rec["model"],
            "secs": round(time.time() - rec["t0"], 2), "tokens": int(tokens or 0),
            "system_prompt": _llmlog_cut(sp, cap), "input": _llmlog_cut(inp, cap),
            "output": _llmlog_cut(out_s, cap),
            "preview": (inp or sp or "").strip().replace("\n", " ")[:140],
            "error": (f"{type(err).__name__}: {err}"[:2000] if err else ""),
            "extra": rec["extra"],
        }
        uid = rec["uid"]

        def _run():
            try:
                _llmlog_col(uid).add(doc)
            except Exception as e:
                print(f"[WARN] llm-log write failed for uid={uid}: {e}")
        threading.Thread(target=_run, daemon=True).start()
    except Exception as e:
        print(f"[WARN] llm-log finish failed: {e}")


def _llmlog_wrap_stream(fn, provider, prompt_kind):
    """জেনারেটর-ধরনের (text, tokens, model) ফাংশনের জন্য। prompt_kind: "parts" বা "prompt"।"""
    sig = _inspect.signature(fn)

    @wraps(fn)
    def wrapper(*a, **kw):
        rec = _llmlog_begin(fn.__name__, provider)
        if rec is None:
            yield from fn(*a, **kw)
            return
        try:
            args = sig.bind_partial(*a, **kw).arguments
            user_text = (_llmlog_parts_text(args.get("prompt_parts")) if prompt_kind == "parts"
                         else args.get("prompt"))
            _llmlog_fill(rec, args.get("system_prompt"), user_text, args.get("model"),
                         {"json_mode": args.get("response_json_mode"),
                          "temperature": args.get("temperature"), "fast": args.get("fast")})
        except Exception as e:
            print(f"[WARN] llm-log fill failed: {e}")
        buf, err, tokens, used = [], None, 0, None
        try:
            for item in fn(*a, **kw):
                buf.append(item[0])
                try:
                    tokens, used = item[1], (item[2] or used)
                except Exception:
                    pass
                yield item
        except GeneratorExit:
            rec["extra"]["note"] = "The stream stopped midway (not fully read)"
            raise
        except BaseException as e:
            err = e
            raise
        finally:
            _llmlog_finish(rec, "".join(buf), err=err, tokens=tokens, model=used)
    return wrapper


def _llmlog_wrap_call(fn, provider, system_arg, user_arg, image_arg=None, extra_args=()):
    """ব্লকিং ফাংশন যা {"text":..., "model":..., ...} dict ফেরত দেয়।"""
    sig = _inspect.signature(fn)

    @wraps(fn)
    def wrapper(*a, **kw):
        rec = _llmlog_begin(fn.__name__, provider)
        if rec is None:
            return fn(*a, **kw)
        try:
            args = sig.bind_partial(*a, **kw).arguments
            user_text = args.get(user_arg) or ""
            if image_arg and args.get(image_arg):
                user_text = f"{user_text}\n\n{_llmlog_image_note('image/jpeg', args.get(image_arg))}"
            _llmlog_fill(rec, args.get(system_arg), user_text, args.get("model"),
                         {k: args.get(k) for k in extra_args})
        except Exception as e:
            print(f"[WARN] llm-log fill failed: {e}")
        try:
            res = fn(*a, **kw)
        except BaseException as e:
            _llmlog_finish(rec, "", err=e)
            raise
        if isinstance(res, dict):
            tok = res.get("tokens") or ((res.get("tin") or 0) + (res.get("tout") or 0))
            _llmlog_finish(rec, res.get("text", ""), tokens=tok, model=res.get("model"),
                           provider=res.get("provider"))
        else:
            _llmlog_finish(rec, res)
        return res
    return wrapper


# গ্লোবাল নাম বদলে দেওয়া হচ্ছে — পুরো ফাইলের সব কলার (stream_ai_raw সহ) এখন থেকে র‍্যাপারটাই ডাকে।
stream_gemini_raw = _llmlog_wrap_stream(stream_gemini_raw, "gemini", "parts")
stream_groq_raw = _llmlog_wrap_stream(stream_groq_raw, "groq", "parts")
stream_groq_chat_raw = _llmlog_wrap_stream(stream_groq_chat_raw, "groq", "prompt")
call_gemini = _llmlog_wrap_call(call_gemini, "gemini", "system_prompt", "prompt",
                                image_arg="image_base64", extra_args=("generation_config",))
call_groq_chat = _llmlog_wrap_call(call_groq_chat, "groq", "system_prompt", "prompt")
_supervisor_llm = _llmlog_wrap_call(_supervisor_llm, "supervisor", "system_prompt", "user_text")


# ---- endpoint: অ্যাপের ভিউয়ার এগুলো ডাকে ----------------------------------

def _llmlog_prune(uid):
    try:
        extra = list(_llmlog_col(uid).order_by("ts_ms", direction="DESCENDING")
                     .offset(_LLMLOG_KEEP).limit(200).select([]).stream())
        for d in extra:
            d.reference.delete()
    except Exception as e:
        print(f"[WARN] llm-log prune failed for uid={uid}: {e}")


@app.route("/api/llm-log/list", methods=["GET"])
@require_session
def llm_log_list():
    uid = g.uid
    try:
        limit = max(1, min(int(request.args.get("limit", 100)), _LLMLOG_KEEP))
    except ValueError:
        limit = 100
    try:
        docs = (_llmlog_col(uid).order_by("ts_ms", direction="DESCENDING").limit(limit)
                .select(["ts_ms", "path", "system", "fn", "provider", "model", "secs",
                         "tokens", "error", "preview"]).stream())
        items = []
        for d in docs:
            row = d.to_dict() or {}
            row["id"] = d.id
            items.append(row)
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    threading.Thread(target=_llmlog_prune, args=(uid,), daemon=True).start()
    return jsonify({"enabled": _llmlog_enabled(uid, force=True), "items": items})


@app.route("/api/llm-log/item", methods=["GET"])
@require_session
def llm_log_item():
    doc_id = (request.args.get("id") or "").strip()
    if not doc_id or "/" in doc_id:
        return jsonify({"error": "bad id"}), 400
    try:
        snap = _llmlog_col(g.uid).document(doc_id).get()
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    if not snap.exists:
        return jsonify({"error": "not found"}), 404
    d = snap.to_dict() or {}
    d["id"] = snap.id
    return jsonify(d)


@app.route("/api/llm-log/delete", methods=["POST"])
@require_session
def llm_log_delete():
    uid = g.uid
    body = request.get_json(silent=True) or {}
    try:
        if body.get("all"):
            deleted = 0
            while True:
                docs = list(_llmlog_col(uid).limit(200).select([]).stream())
                if not docs:
                    break
                batch = get_db().batch()
                for d in docs:
                    batch.delete(d.reference)
                batch.commit()
                deleted += len(docs)
            return jsonify({"ok": True, "deleted": deleted})
        doc_id = (body.get("id") or "").strip()
        if not doc_id or "/" in doc_id:
            return jsonify({"error": "bad id"}), 400
        _llmlog_col(uid).document(doc_id).delete()
        return jsonify({"ok": True, "deleted": 1})
    except Exception as e:
        return jsonify({"error": str(e)}), 502


@app.route("/api/llm-log/toggle", methods=["POST"])
@require_session
def llm_log_toggle():
    uid = g.uid
    on = bool((request.get_json(silent=True) or {}).get("on"))
    try:
        get_db().collection("users").document(uid).set({"llm_trace_on": on}, merge=True)
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    _LLMLOG_ENABLED_CACHE[uid] = (time.time(), on)
    return jsonify({"ok": True, "enabled": on})


@app.before_request
def _llmlog_reset_ctx():
    # একই থ্রেডে আগের রিকোয়েস্টের uid যেন কখনো পরের রিকোয়েস্টে লিক না করে
    _LLMLOG_CTX.set(None)


# ======================================================================
# AI Automation of the Real World (v32, প্রথম অর্ধেক)
#
# অ্যাপের নতুন আইকন → সম্পূর্ণ আলাদা মোড (চ্যাটবট নয়)। ইউজার এখানে "অটোমেশন এজেন্ট" সার্চ করে
# ডাউনলোড করে (যেমন "Make cake with Ai অটোমেশন"); এজেন্টের মেশিন ESP32। অ্যাডমিন প্যানেল
# (/admin-x7k9/automation) থেকে এজেন্ট, তার ফ্রেমওয়ার্ক (ফ্ল্যাশ-পার্ট: অফসেট + বাইনারি) আর
# ডিভাইস-কী দেওয়া হয়; ইউজার শুধু ক্লিক করে ডাউনলোড/ফ্ল্যাশ করে।
#
# Firestore:
#   automation_agents/{id}                      — এজেন্টের মেটা + ফ্ল্যাশ-পার্ট তালিকা + device_key
#   automation_blobs/{blob_id}                  — আপলোড-করা বাইনারির মেটা (name,size,sha256,n)
#   automation_blobs/{blob_id}/chunks/{0000..}  — {"data": bytes} (Firestore ডকের ১ MiB সীমার জন্য টুকরো)
#
# সিকিউরিটি (অ্যাপ ছাড়া কেউ AP-র কন্ট্রোল পেজে ঢুকতে পারবে না): device_key কেবল লগইন-করা
# অ্যাপ ইউজারের কাছে /api/automation/device-key/<id> দিয়ে যায়, সার্চ/ডিটেইলে কখনো যায় না। ESP32
# ফার্মওয়্যার প্রতিটা রিকোয়েস্টে challenge-response (HMAC-SHA256(device_key, nonce)) চায় —
# দেখো AUTOMATION_FRAMEWORK.md।
# ======================================================================

_AUTO_BLOB_CHUNK = 700_000          # প্রতি Firestore চাঙ্কে কাঁচা বাইট (base64 লাগে না, ১ MiB-এর নিচে)
_AUTO_MAX_PART_BYTES = 6_000_000    # একটা ফ্ল্যাশ-পার্টের সর্বোচ্চ সাইজ
_AUTO_TRANSPORTS = ("bluetooth", "wifi", "otg")

_AUTO_SEED_AGENT = {
    "id": "make-cake",
    "title": "Make cake with AI automation",
    "description": "Automation for making a cake with AI — controls an ESP32 machine.",
    "keywords": ["cake", "কেক", "make cake", "baking", "অটোমেশন", "automation"],
}


def _auto_slug(s):
    s = re.sub(r"[^a-z0-9]+", "-", (s or "").lower()).strip("-")
    return s[:48]


def _auto_norm_offset(raw):
    """'0x1000' / '1000' / '1×1000' / '1x800' → '0x1000' / '0x1000' / '0x1000' / '0x800'।
    অ্যাডমিন যেভাবেই লিখুক, হেক্স অফসেট হিসেবে নেওয়া হয়। অবৈধ হলে None।"""
    s = (raw or "").strip().replace("×", "x").replace(" ", "")
    if not s:
        return None
    m = re.match(r"^(?:0x|[0-9]x)([0-9a-fA-F]+)$", s) or re.match(r"^([0-9a-fA-F]+)$", s)
    if not m:
        return None
    return "0x%X" % int(m.group(1), 16)


def _auto_agent_ref(agent_id):
    return get_db().collection("automation_agents").document(agent_id)


def _auto_new_key():
    return uuid.uuid4().hex + uuid.uuid4().hex[:16]


def _auto_ensure_seed():
    """প্রথমবার কিছু না থাকলে 'Make cake' এজেন্টটা বসিয়ে দেয় — ফার্মওয়্যার পরে অ্যাডমিন থেকে।"""
    try:
        col = get_db().collection("automation_agents")
        if next(iter(col.limit(1).stream()), None) is None:
            seed = dict(_AUTO_SEED_AGENT)
            seed.update({
                "machine": "esp32", "transports": list(_AUTO_TRANSPORTS),
                "ap_ssid": "", "ap_password": "", "ap_host": "192.168.4.1",
                "device_key": _auto_new_key(), "version": 1, "enabled": True,
                "bt_name": "", "serial_baud": 115200, "ai_enabled": True, "ai_prompt": "",
                "flash": {"chip": "esp32", "baud": 460800, "parts": []},
                "updated_at": dt.datetime.utcnow().isoformat(),
            })
            col.document(seed["id"]).set(seed)
    except Exception as e:
        print(f"[WARN] automation seed failed: {e}")


def _auto_int(v, default):
    try:
        n = int(str(v).strip())
        return n if n > 0 else default
    except (TypeError, ValueError):
        return default


def _auto_public(d):
    """ইউজারকে যা দেখানো যায় — device_key/ap_password কখনোই নয়।"""
    flash = d.get("flash") or {}
    parts = []
    for p in flash.get("parts", []):
        url = p.get("url") or (f"/api/automation/blob/{p['blob_id']}" if p.get("blob_id") else "")
        parts.append({"offset": p.get("offset"), "name": p.get("name", ""), "size": p.get("size", 0),
                      "sha256": p.get("sha256", ""), "url": url})
    return {
        "id": d.get("id"), "title": d.get("title", ""), "description": d.get("description", ""),
        "machine": d.get("machine", "esp32"), "version": d.get("version", 1),
        "category": d.get("category", ""),
        "thumb_url": (f"/api/automation/thumb/{d.get('id')}?v={int(d.get('thumb_v') or 1)}"
                      if d.get("thumb_blob_id") else ""),
        "transports": [t for t in d.get("transports", _AUTO_TRANSPORTS) if t in _AUTO_TRANSPORTS],
        "ap_ssid": d.get("ap_ssid", ""), "ap_host": d.get("ap_host") or "192.168.4.1",
        "bt_name": d.get("bt_name", ""), "serial_baud": _auto_int(d.get("serial_baud"), 115200),
        "ai_enabled": bool(d.get("ai_enabled", True)),
        "flash": {"chip": flash.get("chip", "esp32"), "baud": int(flash.get("baud", 460800)), "parts": parts},
    }


def _auto_score(d, tokens):
    if not tokens:
        return 1
    hay_title = (d.get("title", "") + " " + d.get("id", "")).lower()
    hay_kw = " ".join(d.get("keywords", [])).lower()
    hay_desc = d.get("description", "").lower()
    score = 0
    for t in tokens:
        if t in hay_title:
            score += 3
        if t in hay_kw:
            score += 2
        if t in hay_desc:
            score += 1
    return score


@app.route("/api/automation/search", methods=["GET"])
@require_session
def automation_search():
    q = (request.args.get("q") or "").strip().lower()
    tokens = [t for t in re.split(r"\s+", q) if t]
    # v37: সার্চ না করলে কিছুই আসে না — এজেন্ট শুধু সার্চ করলেই দেখা যায় (ডাউনলোড-করাগুলো অ্যাপে "আমার এজেন্ট"-এ থাকে)
    if not tokens:
        return jsonify({"agents": []})
    _auto_ensure_seed()
    try:
        docs = [s.to_dict() for s in get_db().collection("automation_agents").stream()]
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    ranked = []
    for d in docs:
        if not d.get("enabled", True):
            continue
        sc = _auto_score(d, tokens)
        if sc > 0:
            ranked.append((sc, d))
    ranked.sort(key=lambda x: (-x[0], x[1].get("title", "")))
    return jsonify({"agents": [_auto_public(d) for _, d in ranked[:30]]})


@app.route("/api/automation/agent/<agent_id>", methods=["GET"])
@require_session
def automation_agent(agent_id):
    try:
        snap = _auto_agent_ref(agent_id).get()
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    if not snap.exists or not snap.to_dict().get("enabled", True):
        return jsonify({"error": "Agent not found."}), 404
    return jsonify({"agent": _auto_public(snap.to_dict())})


@app.route("/api/automation/device-key/<agent_id>", methods=["GET"])
@require_session
def automation_device_key(agent_id):
    """শুধু লগইন-করা অ্যাপ ইউজার পায় (require_session = ব্লকড-ইউজার চেকসহ)। ESP32 AP-র কন্ট্রোল
    পেজ খুলতে অ্যাপ এই কী দিয়ে HMAC বানায়; ap_password-ও এখান থেকেই আসে।"""
    try:
        snap = _auto_agent_ref(agent_id).get()
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    if not snap.exists or not snap.to_dict().get("enabled", True):
        return jsonify({"error": "Agent not found."}), 404
    d = snap.to_dict()
    resp = jsonify({"device_key": d.get("device_key", ""), "ap_ssid": d.get("ap_ssid", ""),
                    "ap_password": d.get("ap_password", ""), "ap_host": d.get("ap_host") or "192.168.4.1",
                    "bt_name": d.get("bt_name", ""), "serial_baud": _auto_int(d.get("serial_baud"), 115200)})
    resp.headers["Cache-Control"] = "no-store"
    return resp


# ---------------------------------------------------------------------------
# AI দিয়ে ESP32 নিয়ন্ত্রণ — সার্ভারের API key-র AI মডেল সিদ্ধান্ত নেয়, অ্যাপ ESP32-তে পৌঁছে দেয়।
# ফার্মওয়্যার নিজে /ai/capabilities-এ ঘোষণা করে সে কী কী পারে; তাই ফ্রেমওয়ার্ক যেমনই হোক এই এন্ডপয়েন্ট বদলাতে হয় না।
# এখানে কোনো শব্দ-মেলানো/সংখ্যা-সীমার গেট নেই: AI অর্থ বুঝে ঠিক করে; একমাত্র কাঠামোগত যাচাই — AI এমন
# অ্যাকশনের নাম দিলে যা ডিভাইস ঘোষণাই করেনি, সেটা ডিভাইসে যাবে না (বাদ পড়া অ্যাকশন AI পরের ধাপে জানতে পারে)।
# ---------------------------------------------------------------------------
AUTOMATION_AI_SYSTEM = """You are the "brain" of a real machine. The machine runs on an ESP32 microcontroller. You cannot send commands directly — at each step you decide the next actions, the app sends them to the ESP32 and returns the result. In this way, in a closed loop (look → think → act → look again), run the machine and fulfil the user's goal.

What you receive at each step:
- goal: what the user wants. It may be written in any language, in any manner — work by meaning, not by specific words.
- capabilities: what the firmware itself has declared it can do — actions (name, description, the type/unit/limits of params; "confirm": true means it runs with the user's permission), sensors, and if there is "safe_stop", the name of the emergency-stop action.
- state: the device's sensors and condition at this moment ("_error" will be there if it could not be read).
- last_results: the result of the actions you sent in the last step (ok/error/user did not allow).
- notes: what you wrote for yourself in the last step — this is your only memory.
- user_feedback: the user's answer to your question (if any).
- elapsed_s: how many seconds have passed since the task began; step: which step number.

Rules:
1. Do not make up an action or param that is not in capabilities. Give params following the declared type, unit and limits (the device also checks them itself, but you must follow them).
2. In the step after sending an action, look at the state and verify whether the task was really done. If not, or if something unexpected happened, think about the cause and correct it; do not blindly send the same failed action again.
3. For time-dependent tasks (heating, mixing, waiting), do not call again and again: give in wait_ms as long as you think is right before looking again. Keep your own estimate of how long it will take using elapsed_s and notes.
4. If something is unclear, preference-dependent or risky, do not guess — ask a short question in ask_user. If something is abnormal (a sensor is unbelievable, an action keeps failing, the device does not respond), give an action that brings the machine to a safe state (safe_stop if there is one) and tell the user.
5. done=true only when you are sure from the state that the goal is truly fulfilled, or you have told the user with the reason that fulfilling it is impossible. Do not give done=true while work remains.
6. say: 1–2 short sentences in the user's language — what you see now and what you are doing. Empty if there is nothing to say.
7. notes: your plan, which steps are finished, running timers/waits (starting from which elapsed_s), what will be needed in the next step — brief but enough for you to pick up from exactly the right place next step.
8. You may give several actions in one step (they will run in order). If there is nothing to do, keep actions empty and give only wait_ms.

Give only this JSON, nothing else:
{"say": "", "actions": [{"action": "name", "params": {}}], "wait_ms": 2000, "done": false, "ask_user": "", "notes": ""}"""
AUTOMATION_AI_SYSTEM = AUTOMATION_AI_SYSTEM + "\n\n" + LANG_RULE


@app.route("/api/automation/ai/decide", methods=["POST"])
@require_session
def automation_ai_decide():
    """
    Body: {agent_id, goal, capabilities{}, state{}, last_results[], notes, user_feedback, elapsed_s, step,
           user_gemini_key?}
    Response: {say, actions[{action, params}], wait_ms, done, ask_user, notes, rejected[], tokens}
    """
    body = request.get_json(silent=True) or {}
    agent_id = str(body.get("agent_id") or "").strip()
    goal = str(body.get("goal") or "").strip()
    if not agent_id or not goal:
        return jsonify({"error": "agent_id and goal are required."}), 400
    try:
        snap = _auto_agent_ref(agent_id).get()
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    if not snap.exists or not snap.to_dict().get("enabled", True):
        return jsonify({"error": "Agent not found."}), 404
    agent = snap.to_dict()
    if not agent.get("ai_enabled", True):
        return jsonify({"error": "AI control is turned off for this agent."}), 403

    caps = body.get("capabilities")
    if not isinstance(caps, dict):
        caps = {}
    state = body.get("state")
    if not isinstance(state, (dict, list)):
        state = {}
    last_results = body.get("last_results")
    if not isinstance(last_results, list):
        last_results = []
    notes = str(body.get("notes") or "")
    feedback = str(body.get("user_feedback") or "")

    uid = g.uid
    user_key = body.get("user_gemini_key")
    gate = _syllabus_token_gate(uid, user_key)
    if gate:
        return gate

    def dump(v):
        return json.dumps(v, ensure_ascii=False)

    machine_ctx = (agent.get("ai_prompt") or "").strip()
    prompt = (
        (f"[Description of this machine and special rules — given by the admin]\n{machine_ctx}\n\n" if machine_ctx else "")
        + f"[goal]\n{goal}\n\n"
        + f"[capabilities]\n{dump(caps)}\n\n"
        + f"[state]\n{dump(state)}\n\n"
        + f"[last_results]\n{dump(last_results)}\n\n"
        + f"[notes]\n{notes or '(this is the first step — nothing has been written yet)'}\n\n"
        + (f"[user_feedback]\n{feedback}\n\n" if feedback else "")
        + f"[elapsed_s] {body.get('elapsed_s', 0)}   [step] {body.get('step', 1)}\n\n"
        + "Now give the specified JSON."
    )

    provider = get_active_provider()
    g.last_input_tokens = 0
    g.last_output_tokens = 0
    g.last_cached_tokens = 0
    raw, tokens, used_model = "", 0, None
    try:
        for piece, tok, model in stream_ai_raw([{"text": prompt}], system_prompt=AUTOMATION_AI_SYSTEM, model=None,
                                               user_key=user_key, response_json_mode=True, provider=provider,
                                               temperature=0.2, fast=True):
            raw += piece
            tokens = tok
            used_model = model
    except AIProviderError as e:
        return jsonify({"error": str(e)}), 502
    except Exception as e:
        return jsonify({"error": f"Unexpected error: {e}"}), 500
    deduct_tokens_async(uid, g.last_input_tokens, g.last_output_tokens, cached_tokens=g.last_cached_tokens)
    log_usage_async(uid, provider, used_model, tokens, "automation:ai_decide")

    parsed = _robust_json_parse((raw or "").strip(), {})
    if not isinstance(parsed, dict) or not parsed:
        return jsonify({"error": "Could not understand the AI's answer — try again.", "tokens": tokens}), 502

    declared = set()
    for a in (caps.get("actions") or []):
        if isinstance(a, dict) and a.get("name"):
            declared.add(str(a["name"]))
    actions, rejected = [], []
    raw_actions = parsed.get("actions")
    if isinstance(raw_actions, list):
        for a in raw_actions:
            if not isinstance(a, dict):
                continue
            name = str(a.get("action") or "").strip()
            if name not in declared:
                rejected.append(f"'{name or '?'}' — the device did not declare this action")
                continue
            params = a.get("params")
            actions.append({"action": name, "params": params if isinstance(params, dict) else {}})
    try:
        wait_ms = max(0, int(float(parsed.get("wait_ms", 2000))))
    except (TypeError, ValueError):
        wait_ms = 2000
    out = {
        "say": str(parsed.get("say") or ""), "actions": actions, "wait_ms": wait_ms,
        "done": bool(parsed.get("done")), "ask_user": str(parsed.get("ask_user") or ""),
        "notes": str(parsed.get("notes") if parsed.get("notes") is not None else notes),
        "rejected": rejected, "tokens": tokens,
    }
    return jsonify(out)


