# ---- সিক্রেট মাস্কিং (ডিফেন্স-ইন-ডেপথ; আসল ভল্ট-মান ডিভাইস থেকে বেরোয়ই না) ---------------------------
_TOOLS_REDACTED = "[REDACTED]"
_TOOLS_SECRET_PATTERNS = (
    re.compile(r"-----BEGIN [A-Z ]*PRIVATE KEY-----.*?(?:-----END [A-Z ]*PRIVATE KEY-----|\Z)", re.S),
    re.compile(r"\bgithub_pat_[A-Za-z0-9_]{20,}"),
    re.compile(r"\bgh[pousr]_[A-Za-z0-9]{20,}"),
    re.compile(r"\bsk-[A-Za-z0-9_\-]{16,}"),
    re.compile(r"\bxox[abprs]-[A-Za-z0-9\-]{10,}"),
    re.compile(r"\bAKIA[0-9A-Z]{16}\b"),
    re.compile(r"\bAIza[0-9A-Za-z_\-]{30,}"),
    re.compile(r"\bgsk_[A-Za-z0-9]{20,}"),
    re.compile(r"\beyJ[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}\.[A-Za-z0-9_\-]{8,}"),
    re.compile(r"(?i)\b(?:bearer|basic)\s+[A-Za-z0-9._~+/\-]{16,}=*"),
)
_TOOLS_URL_CREDS_RE = re.compile(r"(?i)(\b[a-z][a-z0-9+.\-]*://[^/\s:@]+):[^/\s@]+@")
_TOOLS_KV_SECRET_RE = re.compile(
    r"(?i)\b(pass(?:word|wd|phrase|code)?|pwd|pw|secret|token|api[_\-\s]?key|access[_\-\s]?key|private[_\-\s]?key|"
    r"auth(?:orization)?|credential|otp|pin)s?\b(\s*[:=]\s*|\s+is\s+)"
    r"(?:\"([^\"]{3,})\"|'([^']{3,})'|([^\s,;\"'}]{4,}))")
_TOOLS_LONG_TOKEN_RE = re.compile(r"[A-Za-z0-9_\-+/=]{32,}")


def _tools_kv_sub(m):
    val = m.group(3) or m.group(4) or m.group(5) or ""
    if val.startswith("{{vault:"):        # ভল্ট-রেফারেন্স সিক্রেট নয়
        return m.group(0)
    if m.group(2).strip().lower() == "is" and re.fullmatch(r"[A-Za-z]+", val):
        return m.group(0)                  # "…is required" জাতীয় সাধারণ বাক্য, সিক্রেট নয়
    return f"{m.group(1)}{m.group(2)}{_TOOLS_REDACTED}"


def _tools_long_token_sub(m):
    t = m.group(0)
    if re.fullmatch(r"[0-9a-fA-F]{32}|[0-9a-fA-F]{40}|[0-9a-fA-F]{64}", t):
        return t                           # চেকসাম/কমিট-হ্যাশ — সিক্রেট নয়
    if "/" in t and t.count("/") >= 2:
        return t                           # পাথ-সদৃশ
    if re.search(r"[A-Za-z]", t) and re.search(r"\d", t):
        return _TOOLS_REDACTED
    return t


def _tools_mask(text):
    """একটা স্ট্রিং থেকে সিক্রেট-সদৃশ অংশ ঢাকে। বারবার চালালেও একই ফল।"""
    if not isinstance(text, str) or not text:
        return text if isinstance(text, str) else ""
    s = text
    for pat in _TOOLS_SECRET_PATTERNS:
        s = pat.sub(_TOOLS_REDACTED, s)
    s = _TOOLS_URL_CREDS_RE.sub(lambda m: m.group(1) + ":" + _TOOLS_REDACTED + "@", s)
    s = _TOOLS_KV_SECRET_RE.sub(_tools_kv_sub, s)
    s = _TOOLS_LONG_TOKEN_RE.sub(_tools_long_token_sub, s)
    return _redact_secrets(s)


def _tools_mask_obj(obj, _depth=0):
    """নেস্টেড dict/list-এর প্রতিটি স্ট্রিং (কী সহ) মাস্ক করে; গভীরতা ও আকার সীমিত।"""
    if _depth > 8:
        return None
    if isinstance(obj, str):
        return _tools_mask(obj[:20000])
    if isinstance(obj, dict):
        return {_tools_mask(str(k))[:80]: _tools_mask_obj(v, _depth + 1) for k, v in list(obj.items())[:60]}
    if isinstance(obj, (list, tuple)):
        return [_tools_mask_obj(v, _depth + 1) for v in list(obj)[:60]]
    if isinstance(obj, (bool, int, float)) or obj is None:
        return obj
    return _tools_mask(str(obj)[:2000])


def _tools_clip(v, n):
    """যেকোনো মান → মাস্ক-করা, এক-লাইনের (নিয়ন্ত্রণ-অক্ষরহীন), n অক্ষরে ছাঁটা স্ট্রিং। আগে মাস্ক, পরে ছাঁটা
    (উল্টোটা হলে অর্ধেক-কাটা সিক্রেট মাস্কের নিচে ফসকে যেত)।"""
    if v is None:
        return ""
    s = v if isinstance(v, str) else str(v)
    s = _tools_mask(s)
    s = re.sub(r"[\x00-\x08\x0b-\x1f\x7f]", " ", s)
    return s.strip()[:n]


def _tools_clip_list(v, n_items, n_chars):
    if not isinstance(v, list):
        return []
    out = []
    for x in v:
        if isinstance(x, (dict, list)):
            continue
        s = _tools_clip(x, n_chars)
        if s:
            out.append(s)
        if len(out) >= n_items:
            break
    return out


# ---- রেট-লিমিট (ইউজার-প্রতি, ইন-মেমরি স্লাইডিং উইন্ডো) -------------------------------------------
_TOOLS_RATE_RULES = {"plan": (4, 600), "decide": (90, 60), "learn": (30, 60)}   # (সর্বোচ্চ কল, সেকেন্ড)
_tools_rate_hits = {}
_tools_rate_lock = threading.Lock()


def _tools_rate_ok(uid, kind):
    limit, window = _TOOLS_RATE_RULES[kind]
    now = time.time()
    with _tools_rate_lock:
        if len(_tools_rate_hits) > 5000:
            for k in [k for k, v in _tools_rate_hits.items() if not v or now - v[-1] > 700]:
                _tools_rate_hits.pop(k, None)
        hits = [t for t in _tools_rate_hits.get((uid, kind), []) if now - t < window]
        if len(hits) >= limit:
            _tools_rate_hits[(uid, kind)] = hits
            return False
        hits.append(now)
        _tools_rate_hits[(uid, kind)] = hits
        return True


def _tools_gate(uid, kind, need_tokens=True):
    """None = এগোনো যাবে; নইলে (jsonify, status)। অ্যাডমিন-ব্লক require_session-এ আগেই হয়ে গেছে; এখানে আবার দেখা (ডিফেন্স)।"""
    if uid in _blocked_uids:
        return jsonify({"error": "This account has been blocked."}), 403
    if not _tools_rate_ok(uid, kind):
        return jsonify({"error": "Too many requests — slow down.", "code": "RATE_LIMIT"}), 429
    if need_tokens:
        return _syllabus_token_gate(uid, None)
    return None


# ---- স্টেজ → মডেল ম্যাপ (কনফিগযোগ্য; ডিফল্ট: সস্তা = Super Lite executor, শক্তিশালী = planner) ------------
_TOOLS_STAGES = ("constraints", "criteria", "candidates", "research", "scoring", "critic", "final", "decide")
_TOOLS_STAGE_TIER = {"constraints": "executor", "criteria": "executor", "candidates": "planner",
                     "research": "executor", "scoring": "executor", "critic": "planner",
                     "final": "planner", "decide": "executor"}
_tools_stage_overrides = {}
_tools_stage_loaded = False


def _tools_load_stage_overrides():
    global _tools_stage_loaded
    if _tools_stage_loaded:
        return
    _tools_stage_loaded = True
    if _db is not None:
        try:
            snap = get_db().collection("settings").document("tools_stage_models").get()
            if snap.exists:
                for st, v in (snap.to_dict() or {}).items():
                    if st in _TOOLS_STAGES and isinstance(v, dict) and v.get("provider") in ("gemini", "groq") and v.get("model"):
                        _tools_stage_overrides[st] = (v["provider"], str(v["model"]))
        except Exception as e:
            print(f"[WARN] tools stage-model load failed: {e}")


def get_tools_stage_model(stage):
    """ক্রম: set_tools_stage_model/Firestore settings/tools_stage_models → env TOOLS_MODEL_<STAGE>="provider:model" → ডিফল্ট টিয়ার।"""
    _tools_load_stage_overrides()
    if stage in _tools_stage_overrides:
        return _tools_stage_overrides[stage]
    env = os.environ.get(f"TOOLS_MODEL_{str(stage).upper()}", "")
    if ":" in env:
        prov, mod = env.split(":", 1)
        if prov in ("gemini", "groq") and mod.strip():
            return prov, mod.strip()
    return get_super_lite_model(_TOOLS_STAGE_TIER.get(stage, "executor"))


def set_tools_stage_model(stage, provider, model):
    if stage not in _TOOLS_STAGES or provider not in ("gemini", "groq") or not model:
        return False
    _tools_load_stage_overrides()
    _tools_stage_overrides[stage] = (provider, str(model))
    if _db is not None:
        try:
            get_db().collection("settings").document("tools_stage_models").set(
                {stage: {"provider": provider, "model": str(model)}}, merge=True)
        except Exception as e:
            print(f"[WARN] tools stage-model save failed: {e}")
    return True


# ---- LLM কল + বিলিং মিটার ------------------------------------------------------------------------
class _ToolsMeter:
    """থ্রেড-নিরাপদ টোকেন-গণনা; flush() = এই পর্যন্ত খরচ একবারে ওয়ালেট থেকে কাটা (ধাপ-প্রতি/কল-প্রতি)।"""

    def __init__(self, uid):
        self.uid = uid
        self.lock = threading.Lock()
        self.tin = 0
        self.tout = 0
        self.provider = "gemini"
        self.model = ""

    def add(self, r):
        with self.lock:
            self.tin += int(r.get("tin") or 0)
            self.tout += int(r.get("tout") or 0)
            self.provider = r.get("provider") or self.provider
            self.model = r.get("model") or self.model

    def flush(self, label):
        with self.lock:
            tin, tout, prov, mod = self.tin, self.tout, self.provider, self.model
            self.tin = self.tout = 0
        if tin or tout:
            deduct_tokens_async(self.uid, tin, tout)
            log_usage_async(self.uid, prov, mod, tin + tout, f"tools:{label}")
        return tin, tout


def _tools_split_tokens(total, prompt_text, out_text):
    """provider শুধু মোট টোকেন দেয় — আউটপুট অনুমান করে বাকিটা ইনপুট ধরা (ইনপুট সস্তা, তাই এটাই ন্যায্য)।"""
    out_est = _estimate_tokens(out_text)
    if total and total > 0:
        tout = min(out_est, int(total))
        return max(0, int(total) - tout), tout
    return _estimate_tokens(prompt_text), out_est


def _tools_llm(stage, system, prompt, grounded=False, timeout=60):
    """একটা স্টেজের LLM কল। প্রম্পট আবার মাস্ক হয় (শেষ দরজা)। প্রধান provider ব্যর্থ হলে অন্যটায় একবার।
    ফেরত: {text, tin, tout, model, provider, sources}. ব্যর্থ হলে AIProviderError।"""
    prompt = _tools_mask(prompt)
    provider, model = get_tools_stage_model(stage)
    other = "groq" if provider == "gemini" else "gemini"
    attempts = [(provider, model), (other, get_default_model(other))]
    if grounded:   # গ্রাউন্ডেড সার্চ শুধু Gemini-তে; স্টেজের provider যাই হোক আগে সেটা, ব্যর্থ হলে সাধারণ কল
        attempts.insert(0, ("gemini_grounded", model if provider == "gemini" else None))
    last_err = None
    for prov, mod in attempts:
        try:
            if prov == "gemini_grounded":
                q = (system + "\n\n" + prompt) if system else prompt
                r = call_gemini_grounded(q, model=mod)
                tin, tout = _tools_split_tokens(r.get("tokens"), q, r.get("text", ""))
                return {"text": r.get("text", ""), "tin": tin, "tout": tout, "model": mod or GEMINI_LEARNING_RESEARCH_MODEL,
                        "provider": "gemini", "sources": r.get("sources") or [], "grounded": bool(r.get("sources"))}
            if prov == "groq":
                r = call_groq_chat(prompt, system_prompt=system, model=mod, timeout=timeout)
            else:
                r = call_gemini(prompt, system_prompt=system, model=mod, timeout=timeout,
                                generation_config={"temperature": 0.2, "responseMimeType": "application/json"})
            tin, tout = _tools_split_tokens(r.get("tokens"), (system or "") + prompt, r.get("text", ""))
            return {"text": r.get("text", ""), "tin": tin, "tout": tout, "model": r.get("model") or mod,
                    "provider": prov, "sources": [], "grounded": False}
        except AIProviderError as e:
            last_err = e
            print(f"[tools] stage={stage} provider={prov} failed: {_redact_secrets(str(e))[:160]}")
        except Exception as e:
            last_err = AIProviderError(f"Unexpected error: {_redact_secrets(str(e))[:160]}")
            print(f"[tools] stage={stage} provider={prov} error: {_redact_secrets(str(e))[:160]}")
    raise last_err or AIProviderError("No provider available.")


def _tools_json(text):
    """মডেলের উত্তর → dict (খালি dict = বোঝা যায়নি)।"""
    parsed = _robust_json_parse((text or "").strip(), {})
    return parsed if isinstance(parsed, dict) else {}


# ---- স্টেপ/ডিটেক্টর স্যানিটাইজার (sanitize_highlight_response-এর ধাঁচে: হোয়াইটলিস্ট + সীমা + risk বাধ্যতামূলক) ----
_TOOLS_ARG_LONG_KEYS = ("command", "text", "content", "query", "question", "url")
_TOOLS_HIGH_RE = re.compile(
    r"(?i)(\bgit\s+push\b|--force|--force-with-lease|\bpush\s+\+|\brm\s+-|\breset\s+--hard\b|\bclean\s+-[a-z]*f|\bbranch\s+-D\b|"
    r"\b(pay|payment|purchase|checkout|place order|subscribe|donate|transfer funds|withdraw|publish|delete account|"
    r"deactivate|change password|revoke|make public|share secret)\b)")
_TOOLS_MEDIUM_RE = re.compile(r"(?i)(\bgit\s+(commit|merge|rebase|stash|tag)\b|\b(overwrite|submit|send|post)\b)")


def _tools_escalate_risk(step):
    """সার্ভারের নিয়ম শুধু ঝুঁকি বাড়ায়, কমায় না (আসল শ্রেণীবিভাগ ডিভাইসের নিয়ম-তালিকায়)।"""
    risk = step["risk"]
    ws, act = step["workspace"], step["action"]
    blob = re.sub(r"\{\{vault:[^{}]*\}\}", "", act + " " + json.dumps(step.get("args") or {}, ensure_ascii=False))
    floor = "low"
    if ws == "storage" and act == "delete":
        floor = "high"
    elif _TOOLS_HIGH_RE.search(blob):
        floor = "high"
    elif ws == "storage" and act in ("write", "move", "unzip", "zip", "export") or act == "upload_file" or _TOOLS_MEDIUM_RE.search(blob):
        floor = "medium"
    if _TOOLS_RISKS.index(floor) > _TOOLS_RISKS.index(risk):
        return floor
    return risk


def _tools_sanitize_args(args, workspace):
    out = {}
    if not isinstance(args, dict):
        return out
    for k, v in list(args.items())[:12]:
        key = re.sub(r"[^A-Za-z0-9_]", "", str(k))[:32]
        if not key:
            continue
        if isinstance(v, bool):
            out[key] = v
        elif isinstance(v, (int, float)):
            if isinstance(v, float) and (v != v or v in (float("inf"), float("-inf"))):
                continue
            out[key] = v
        elif isinstance(v, str):
            out[key] = _tools_clip(v, 600 if key in _TOOLS_ARG_LONG_KEYS else 300)
        elif isinstance(v, list) and key == "options":
            out[key] = _tools_clip_list(v, 4, 60)
        elif isinstance(v, (list, dict)):
            out[key] = _tools_clip(json.dumps(v, ensure_ascii=False), 300)
    return out


def _tools_sanitize_detector(d):
    if isinstance(d, str):
        d = {"type": d}
    if not isinstance(d, dict):
        return {"type": "timeout"}
    t = str(d.get("type") or "").strip().lower()
    t = _TOOLS_DETECTOR_ALIASES.get(t, t)
    if t not in _TOOLS_DETECTORS:
        return {"type": "timeout"}
    params = _tools_sanitize_args({k: v for k, v in d.items() if k != "type"}, "detector")
    return {"type": t, **params}


def _tools_sanitize_step(raw, idx, used_ids, now=None):
    """একটা স্টেপ → (clean_step | None, rejection_reason | None)।"""
    if not isinstance(raw, dict):
        return None, f"step {idx}: not an object"
    ws = str(raw.get("workspace") or "").strip().lower()
    act = str(raw.get("action") or "").strip().lower()
    if ws not in _TOOLS_WORKSPACES:
        return None, f"step {idx}: workspace '{_tools_clip(ws, 20) or '?'}' not allowed"
    if act not in _TOOLS_ACTIONS[ws]:
        return None, f"step {idx}: action '{_tools_clip(act, 30) or '?'}' not allowed for {ws}"
    args = _tools_sanitize_args(raw.get("args"), ws)
    now = now or int(time.time())
    if ws == "wait" and act == "until":
        try:
            ts = int(float(args.get("until_ts")))
        except (TypeError, ValueError):
            return None, f"step {idx}: wait.until needs a numeric until_ts"
        if ts < now - 60 or ts > now + _TOOLS_MAX_WAIT_AHEAD_S:
            return None, f"step {idx}: until_ts out of range"
        args["until_ts"] = ts
    if ws == "wait" and act == "sleep":
        try:
            args["seconds"] = max(1, min(86400, int(float(args.get("seconds", 60)))))
        except (TypeError, ValueError):
            args["seconds"] = 60
    if ws == "ask_user" and not str(args.get("question") or "").strip():
        return None, f"step {idx}: ask_user needs a question"
    if ws == "shell" and not str(args.get("command") or "").strip():
        return None, f"step {idx}: shell.run needs args.command"
    sid = re.sub(r"[^A-Za-z0-9_\-]", "", str(raw.get("id") or ""))[:24]
    if not sid or sid in used_ids:
        sid = f"s{idx}"
        while sid in used_ids:
            sid += "x"
    used_ids.add(sid)
    try:
        timeout_s = max(1, min(86400, int(float(raw.get("timeout_s", 120)))))
    except (TypeError, ValueError):
        timeout_s = 120
    risk = str(raw.get("risk") or "").strip().lower()
    note = None
    if risk not in _TOOLS_RISKS:
        risk = "high"                 # risk ফিল্ড বাধ্যতামূলক — না থাকলে/ভুল হলে সবচেয়ে সতর্ক মান
        note = f"step {idx}: risk missing/invalid → high"
    on_fail = str(raw.get("on_fail") or "").strip().lower()
    if on_fail not in _TOOLS_ON_FAIL:
        on_fail = "replan"
    step = {"id": sid, "workspace": ws, "action": act, "args": args,
            "detector": _tools_sanitize_detector(raw.get("detector")),
            "timeout_s": timeout_s, "risk": risk, "on_fail": on_fail}
    step["risk"] = _tools_escalate_risk(step)
    return step, note


def _tools_sanitize_steps(raw_steps, max_steps):
    """→ (steps, notes)। notes = বাদ পড়া/বদলানো স্টেপের কারণ (ক্লায়েন্টকে `rejected` হিসেবে যায়)।"""
    steps, notes, used = [], [], set()
    if not isinstance(raw_steps, list):
        return steps, notes
    for i, raw in enumerate(raw_steps[: max_steps * 2], start=1):
        if len(steps) >= max_steps:
            break
        st, why = _tools_sanitize_step(raw, i, used)
        if why:
            notes.append(why)
        if st:
            steps.append(st)
    return steps, notes


def sanitize_tools_decide_response(parsed, vault_titles=None, now=None):
    """/api/tools/decide-এর স্যানিটাইজার। ফেরত: (clean_dict, rejected[])। মডেলের কিছুই সরাসরি বিশ্বাস করা হয় না।"""
    rejected = []
    now = now or int(time.time())
    clean = {"note": "", "status": "continue", "say": "", "steps": [], "wait_until": None,
             "ask_user": None, "edit_goal": None, "done": False}
    if not isinstance(parsed, dict):
        return clean, ["response was not an object"]
    clean["note"] = _tools_clip(parsed.get("note"), 300)
    clean["say"] = _tools_clip(parsed.get("say"), 400)
    status = str(parsed.get("status") or "continue").strip().lower()
    if status not in _TOOLS_STATUSES:
        rejected.append(f"status '{_tools_clip(status, 20)}' not allowed → continue")
        status = "continue"
    steps, notes = _tools_sanitize_steps(parsed.get("steps"), _TOOLS_MAX_DECIDE_STEPS)
    if vault_titles is not None:        # মডেল শুধু দেওয়া ভল্ট-টাইটেল ব্যবহার করতে পারে — বানানো টাইটেলের স্টেপ বাদ
        known, ok_steps = set(vault_titles), []
        for st in steps:
            refs = re.findall(r"\{\{vault:([^.{}]{1,60})\.[^{}]{1,60}\}\}", json.dumps(st, ensure_ascii=False))
            bad = [r for r in refs if r.strip() not in known]
            if bad:
                notes.append(f"step {st['id']}: unknown vault title '{_tools_clip(bad[0], 30)}'")
            else:
                ok_steps.append(st)
        steps = ok_steps
    clean["steps"], rejected = steps, rejected + notes
    wu = parsed.get("wait_until")
    if wu not in (None, "", False):
        try:
            ts = int(float(wu))
            if now - 60 <= ts <= now + _TOOLS_MAX_WAIT_AHEAD_S:
                clean["wait_until"] = ts
            else:
                rejected.append("wait_until out of range")
        except (TypeError, ValueError):
            rejected.append("wait_until not numeric")
    au = parsed.get("ask_user")
    if isinstance(au, str) and au.strip():
        au = {"question": au}
    if isinstance(au, dict) and str(au.get("question") or "").strip():
        clean["ask_user"] = {"question": _tools_clip(au.get("question"), 300),
                             "options": _tools_clip_list(au.get("options"), 4, 60)}
    eg = parsed.get("edit_goal")
    if isinstance(eg, str) and eg.strip():
        clean["edit_goal"] = _tools_clip(eg, 300)
    clean["done"] = bool(parsed.get("done")) or status == "done"
    if clean["done"]:
        status, clean["steps"] = "done", []
    if clean["ask_user"] and status in ("continue", "step_done"):
        status = "needs_you"
    if clean["wait_until"] and status in ("continue", "step_done"):
        status = "wait"
    clean["status"] = status
    return clean, rejected


# ---- RAG "pipelines": top-k খোঁজ ও লেখা -------------------------------------------------------------
def _tools_rag_topk(query, k=3):
    """যাচাই-করা রেসিপি আগে, তারপর স্কোর। কোনো ব্যর্থতায় খালি তালিকা (fail-open, প্ল্যান তখনও চলে)।"""
    try:
        notes = list_rag_notes(kind="pipelines")
        if not notes:
            return []
        q = embed_text(_tools_mask(query), task_type="RETRIEVAL_QUERY")
        if not q:
            return []
        scored = []
        for n in notes:
            emb = n.get("embedding")
            if not emb:
                continue
            sc = cosine_similarity(q, emb)
            if sc >= RAG_TOPIC_THRESHOLD:
                scored.append((1 if n.get("verified") else 0, sc, n))
        scored.sort(key=lambda t: (t[0], t[1]), reverse=True)
        return [n for _v, _s, n in scored[:k]]
    except Exception as e:
        print(f"[WARN] tools rag search failed: {_redact_secrets(str(e))[:120]}")
        return []


def _tools_recipe_line(n):
    tag = "verified" if n.get("verified") else "unverified"
    body = re.sub(r"\s+", " ", str(n.get("content") or ""))[:420]
    return f"[{tag}] {_tools_clip(n.get('title'), 80)}: {body}"


_TOOLS_EMAIL_RE = re.compile(r"[\w.+\-]+@[\w\-]+\.[\w.\-]+")
_TOOLS_DIGITS_RE = re.compile(r"\+?\d[\d\s\-().]{6,}\d")


def _tools_scrub_pii(s):
    """শেয়ার্ড ভল্টে যাওয়া লেখা থেকে ইমেইল/ফোন-সদৃশ বাদ (ডেটা-সংরক্ষণ নিরাপত্তা)।"""
    s = _TOOLS_EMAIL_RE.sub("[email]", s)
    return _TOOLS_DIGITS_RE.sub("[number]", s)


# ---- ইনপুট স্যানিটাইজ (প্রতিটি ফিল্ড মাস্ক হয়ে তবে ঢোকে) ----------------------------------------------
def _tools_session_id(body):
    sid = str(body.get("session_id") or "").strip()
    return sid if _TOOLS_SESSION_RE.match(sid) else ""


def _tools_compact_obj(obj, max_chars):
    obj = _tools_mask_obj(obj)
    try:
        s = json.dumps(obj, ensure_ascii=False, separators=(",", ":"))
    except (TypeError, ValueError):
        s = ""
    return s[:max_chars]


def _tools_compact_steps(steps, n=8):
    out = []
    if not isinstance(steps, list):
        return out
    for s in steps[:n]:
        if isinstance(s, dict):
            ws = _tools_clip(s.get("workspace"), 12)
            act = _tools_clip(s.get("action"), 20)
            arg = ""
            if isinstance(s.get("args"), dict):
                arg = _tools_clip(json.dumps(s["args"], ensure_ascii=False), 120)
            out.append(f"{_tools_clip(s.get('id'), 24)} {ws}.{act} {arg}".strip())
        elif isinstance(s, str):
            out.append(_tools_clip(s, 160))
    return out


# ============================ POST /api/tools/plan (SSE) ============================
_TOOLS_POOL = _cf.ThreadPoolExecutor(max_workers=12, thread_name_prefix="tools")


def _tools_submit(fn, *a):
    ctx = contextvars.copy_context()      # LLM-লগের ইউজার-কনটেক্সট থ্রেডে নিয়ে যাওয়া
    return _TOOLS_POOL.submit(ctx.run, fn, *a)


def _tools_wait(fut):
    """ব্লকিং কলের সময় প্রতি ৮ সেকেন্ডে SSE-কমেন্ট (প্রক্সি যেন সংযোগ না কাটে)। `res = yield from _tools_wait(f)`।"""
    while True:
        try:
            return fut.result(timeout=8)
        except _cf.TimeoutError:
            yield ": ping\n\n"


def _tools_normalize_criteria(raw):
    crit, seen = [], set()
    if isinstance(raw, list):
        for c in raw[:10]:
            if not isinstance(c, dict):
                continue
            name = re.sub(r"[^a-z0-9_]", "", str(c.get("name") or "").strip().lower().replace(" ", "_"))[:32]
            if not name or name in seen:
                continue
            try:
                w = float(c.get("weight"))
            except (TypeError, ValueError):
                w = 0.1
            if w != w:
                w = 0.1
            seen.add(name)
            crit.append({"name": name, "weight": max(0.0, min(1.0, w)), "why": _tools_clip(c.get("why"), 100)})
    for base in _TOOLS_BASE_CRITERIA:          # স্পেক: সময়, মান, খরচ, নির্ভরযোগ্যতা সবসময় থাকবে
        if base not in seen:
            crit.append({"name": base, "weight": 0.1, "why": ""})
    crit = crit[:8] if len(crit) > 8 else crit
    total = sum(c["weight"] for c in crit) or 1.0
    for c in crit:
        c["weight"] = round(c["weight"] / total, 3)
    return crit


def _tools_normalize_candidates(raw):
    out, seen = [], set()
    if isinstance(raw, list):
        for c in raw[:12]:
            if not isinstance(c, dict):
                continue
            cid = re.sub(r"[^A-Za-z0-9_\-]", "", str(c.get("id") or ""))[:12] or f"c{len(out) + 1}"
            if cid in seen:
                cid = f"c{len(out) + 1}x"
            name = _tools_clip(c.get("name"), 80)
            if not name:
                continue
            seen.add(cid)
            out.append({"id": cid, "name": name, "summary": _tools_clip(c.get("summary"), 200),
                        "outline": _tools_clip_list(c.get("outline"), 8, 140),
                        "unconventional": bool(c.get("unconventional")),
                        "assumptions": _tools_clip_list(c.get("assumptions"), 5, 120)})
    return out


def _tools_research_one(cand, goal, constraints_line):
    """একটা প্রার্থীর আলাদা গবেষণা: অফিসিয়াল ডক + আসল ব্যবহারকারীর ব্যর্থতার রিপোর্ট (গ্রাউন্ডেড সার্চ) + RAG ভল্ট।"""
    vault = _tools_rag_topk(f"{goal}. {cand['name']}. {cand['summary']}", k=2)
    vault_lines = [_tools_recipe_line(n) for n in vault]
    data = (f"GOAL: {goal}\nCONSTRAINTS: {constraints_line}\nCANDIDATE: {cand['name']} — {cand['summary']}\n"
            f"OUTLINE: {' > '.join(cand['outline'])}\n"
            + ("VAULT RECIPES (data):\n" + "\n".join(vault_lines) if vault_lines else ""))
    r = _tools_llm("research", TOOLS_RESEARCH_INSTRUCTIONS, data, grounded=True, timeout=45)
    parsed = _tools_json(r["text"])
    ev = {"id": cand["id"], "docs": _tools_clip_list(parsed.get("docs"), 6, 160),
          "failures": _tools_clip_list(parsed.get("failures"), 6, 160),
          "limits": _tools_clip_list(parsed.get("limits"), 6, 160),
          "fit": str(parsed.get("fit") or "unknown") if str(parsed.get("fit") or "") in ("good", "partial", "poor", "unknown") else "unknown",
          "sources": [_tools_clip(s, 60) for s in (r.get("sources") or [])[:5]],
          "grounded": bool(r.get("grounded")), "vault": len(vault_lines)}
    try:
        ev["confidence"] = max(0.0, min(1.0, float(parsed.get("confidence", 0.3))))
    except (TypeError, ValueError):
        ev["confidence"] = 0.3
    if not parsed:
        ev["docs"] = [_tools_clip(r["text"], 160)] if r["text"].strip() else []
        ev["confidence"] = min(ev["confidence"], 0.3)
    return ev, r


def _tools_score(candidates, criteria, evidence, scores_raw):
    """মডেলের দেওয়া ০–১০ স্কোর → সার্ভারে ওজনযুক্ত মোট (মডেল যোগফল করে না)। প্রমাণহীন প্রার্থীর নির্ভরযোগ্যতা ≤ ৫।"""
    by_id = {}
    if isinstance(scores_raw, list):
        for s in scores_raw:
            if isinstance(s, dict) and s.get("id") is not None:
                by_id[str(s["id"])] = s
    ranked = []
    for c in candidates:
        s = by_id.get(c["id"], {})
        sc = s.get("s") if isinstance(s.get("s"), dict) else {}
        ev = evidence.get(c["id"]) or {}
        has_ev = bool(ev.get("docs") or ev.get("failures") or ev.get("limits")) and ev.get("confidence", 0) >= 0.3
        per, total = {}, 0.0
        for cr in criteria:
            try:
                v = max(0.0, min(10.0, float(sc.get(cr["name"], 3))))
            except (TypeError, ValueError):
                v = 3.0
            if cr["name"] == "reliability" and not has_ev:
                v = min(v, 5.0)
            per[cr["name"]] = round(v, 1)
            total += cr["weight"] * v / 10.0
        ranked.append({**c, "scores": per, "total": round(total, 3), "note": _tools_clip(s.get("note"), 140),
                       "evidence": has_ev})
    ranked.sort(key=lambda x: x["total"], reverse=True)
    return ranked


def _tools_estimate(raw):
    e = raw if isinstance(raw, dict) else {}
    def num(v, hi):
        try:
            f = float(v)
            return max(0.0, min(hi, f)) if f == f else None
        except (TypeError, ValueError):
            return None
    ts, cu = num(e.get("time_s"), 1e7), num(e.get("cost_usd"), 1e6)
    return {"time": _tools_clip(e.get("time"), 40), "cost": _tools_clip(e.get("cost"), 40),
            "time_s": int(ts) if ts is not None else None, "cost_usd": cu}


def _tools_balance_ok(uid):
    try:
        bal = get_token_balance(uid)
        return bal["input_tokens"] > 0 and bal["output_tokens"] > 0
    except Exception:
        return True      # ব্যালেন্স পড়া ব্যর্থ হলে কাজ থামাই না (অন্য এন্ডপয়েন্টের মতোই fail-open)


@app.route("/api/tools/plan", methods=["POST"])
@require_session
def tools_plan():
    """
    Body: {goal, device_info{}, hints?, session_id?}
    SSE events (সবই JSON, "type" সহ):
      {"type":"stage","stage":"constraints|criteria|candidates|research|scoring|critic|final","status":"running|progress|done", ...summary}
      {"type":"done","result":{"plan":{"steps":[...],"pipeline":{id,name,summary}},"alternatives":[...],
                               "rationale":"...","estimate":{time,cost,time_s,cost_usd},"warnings":[...]}}
      {"type":"error","error":"...","code":"..."}
    """
    body = request.get_json(silent=True) or {}
    goal = _tools_clip(body.get("goal"), 1200)
    if not goal:
        return jsonify({"error": "goal is required"}), 400
    uid = g.uid
    gate = _tools_gate(uid, "plan")
    if gate:
        return gate
    sid = _tools_session_id(body)
    device = _tools_compact_obj(body.get("device_info") if isinstance(body.get("device_info"), dict) else {}, 800)
    hints_raw = body.get("hints")
    hints = _tools_clip("; ".join(str(h) for h in hints_raw[:8]) if isinstance(hints_raw, list) else hints_raw, 600)
    meter = _ToolsMeter(uid)

    def gen():
        warnings = []

        def stage(name, status, **extra):
            return sse("stage", stage=name, status=status, session_id=sid, **extra)

        def fail(msg, code="PLAN_FAILED"):
            return sse("error", error=msg, code=code, session_id=sid)

        try:
            # 1) সীমাবদ্ধতা (সস্তা মডেল)
            yield stage("constraints", "running")
            data = f"GOAL: {goal}\nDEVICE: {device or '{}'}\nHINTS: {hints or '-'}"
            r = yield from _tools_wait(_tools_submit(_tools_llm, "constraints", TOOLS_CONSTRAINTS_INSTRUCTIONS, data))
            meter.add(r)
            pc = _tools_json(r["text"])
            cons = {"goal_type": _tools_clip(pc.get("goal_type"), 80), "hard": _tools_clip_list(pc.get("hard"), 8, 120),
                    "soft": _tools_clip_list(pc.get("soft"), 8, 120), "unknowns": _tools_clip_list(pc.get("unknowns"), 8, 120),
                    "device": _tools_clip_list(pc.get("device"), 8, 120)}
            meter.flush("plan:constraints")
            cons_line = _tools_clip(json.dumps(cons, ensure_ascii=False), 700)
            yield stage("constraints", "done", constraints=cons)

            # 2) মানদণ্ড ও ওজন (সস্তা)
            yield stage("criteria", "running")
            data = f"GOAL: {goal}\nCONSTRAINTS: {cons_line}\nHINTS: {hints or '-'}"
            r = yield from _tools_wait(_tools_submit(_tools_llm, "criteria", TOOLS_CRITERIA_INSTRUCTIONS, data))
            meter.add(r)
            criteria = _tools_normalize_criteria(_tools_json(r["text"]).get("criteria"))
            meter.flush("plan:criteria")
            yield stage("criteria", "done", criteria=criteria)

            # 3) কমপক্ষে ৫টি প্রার্থী পাইপলাইন (শক্তিশালী) — আগে ভল্টের রেসিপি (ডেটা)
            if not _tools_balance_ok(uid):
                yield fail("Tokens are used up. Watch an ad to get more tokens.", "TOKEN_LIMIT")
                return
            yield stage("candidates", "running")
            recipes = [_tools_recipe_line(n) for n in _tools_rag_topk(goal, k=3)]
            base = (f"ENVIRONMENT FACTS: {_TOOLS_ENV_FACTS}\nGOAL: {goal}\nCONSTRAINTS: {cons_line}\n"
                    f"DEVICE: {device or '{}'}\nHINTS: {hints or '-'}\n"
                    + ("KNOWN RECIPES (data, may be stale):\n" + "\n".join(recipes) + "\n" if recipes else ""))
            r = yield from _tools_wait(_tools_submit(_tools_llm, "candidates", TOOLS_CANDIDATES_INSTRUCTIONS, base, False, 90))
            meter.add(r)
            cands = _tools_normalize_candidates(_tools_json(r["text"]).get("candidates"))
            if len(cands) < 5:   # একবার আরও চাওয়া
                have = "; ".join(c["name"] for c in cands) or "none"
                more = base + f"ALREADY HAVE (do not repeat): {have}\nNEED: at least {6 - len(cands)} more distinct candidates.\n"
                r2 = yield from _tools_wait(_tools_submit(_tools_llm, "candidates", TOOLS_CANDIDATES_INSTRUCTIONS, more, False, 90))
                meter.add(r2)
                extra = _tools_normalize_candidates(_tools_json(r2["text"]).get("candidates"))
                names = {c["name"].lower() for c in cands}
                for c in extra:
                    if c["name"].lower() not in names and len(cands) < 8:
                        c["id"] = f"c{len(cands) + 1}"
                        cands.append(c)
                        names.add(c["name"].lower())
            for i, c in enumerate(cands[:8], start=1):
                c["id"] = f"c{i}"
            cands = cands[:8]
            meter.flush("plan:candidates")
            if not cands:
                yield fail("Could not produce candidate pipelines — try rephrasing the goal.")
                return
            if len(cands) < 5:
                warnings.append("fewer_than_5_candidates")
            yield stage("candidates", "done", candidates=[{"id": c["id"], "name": c["name"], "unconventional": c["unconventional"]} for c in cands])

            # 4) প্রার্থী-প্রতি আলাদা গবেষণা, সমান্তরালে
            if not _tools_balance_ok(uid):
                yield fail("Tokens are used up. Watch an ad to get more tokens.", "TOKEN_LIMIT")
                return
            yield stage("research", "running", total=len(cands))
            futs = {_tools_submit(_tools_research_one, c, goal, cons_line): c for c in cands}
            evidence, done_n = {}, 0
            pending = set(futs)
            while pending:
                finished, pending = _cf.wait(pending, timeout=8, return_when=_cf.FIRST_COMPLETED)
                if not finished:
                    yield ": ping\n\n"
                    continue
                for f in finished:
                    c = futs[f]
                    done_n += 1
                    try:
                        ev, rr = f.result()
                        meter.add(rr)
                        evidence[c["id"]] = ev
                    except Exception as e:
                        print(f"[tools] research failed for {c['id']}: {_redact_secrets(str(e))[:120]}")
                        evidence[c["id"]] = {"id": c["id"], "docs": [], "failures": [], "limits": [], "fit": "unknown",
                                             "sources": [], "grounded": False, "vault": 0, "confidence": 0.0}
                        warnings.append(f"research_unavailable:{c['id']}")
                    yield stage("research", "progress", done=done_n, total=len(cands), candidate=c["name"])
            meter.flush("plan:research")
            yield stage("research", "done", evidence={k: {"fit": v["fit"], "confidence": v["confidence"], "sources": v["sources"]}
                                                      for k, v in evidence.items()})

            # 5) প্রমাণভিত্তিক স্কোরিং (সস্তা)
            yield stage("scoring", "running")
            ev_lines = []
            for c in cands:
                ev = evidence[c["id"]]
                ev_lines.append(f"{c['id']} | {c['name']} | {c['summary']}\n  docs: {'; '.join(ev['docs']) or 'none'}\n"
                                f"  failures: {'; '.join(ev['failures']) or 'none'}\n  limits: {'; '.join(ev['limits']) or 'none'}\n"
                                f"  fit={ev['fit']} confidence={ev['confidence']}")
            data = (f"GOAL: {goal}\nCRITERIA: {json.dumps([{'name': c['name'], 'weight': c['weight']} for c in criteria])}\n"
                    "CANDIDATES AND EVIDENCE:\n" + "\n".join(ev_lines))
            r = yield from _tools_wait(_tools_submit(_tools_llm, "scoring", TOOLS_SCORING_INSTRUCTIONS, data))
            meter.add(r)
            ranked = _tools_score(cands, criteria, evidence, _tools_json(r["text"]).get("scores"))
            meter.flush("plan:scoring")
            yield stage("scoring", "done", ranking=[{"id": c["id"], "name": c["name"], "total": c["total"]} for c in ranked])

            # 6) সমালোচক-পাস (শক্তিশালী) — শীর্ষ ৩
            yield stage("critic", "running")
            short = ranked[:3]
            data = (f"ENVIRONMENT FACTS: {_TOOLS_ENV_FACTS}\nGOAL: {goal}\nCONSTRAINTS: {cons_line}\nSHORTLIST:\n"
                    + "\n".join(f"{c['id']} | {c['name']} | total={c['total']} | {c['summary']} | outline: {' > '.join(c['outline'])}\n"
                                f"  scores={json.dumps(c['scores'])} note={c['note']}\n  failures: {'; '.join(evidence[c['id']]['failures']) or 'none'}"
                                for c in short))
            r = yield from _tools_wait(_tools_submit(_tools_llm, "critic", TOOLS_CRITIC_INSTRUCTIONS, data))
            meter.add(r)
            pk = _tools_json(r["text"])
            pref = str(pk.get("preferred_id") or "")
            chosen = next((c for c in short if c["id"] == pref), short[0])
            critic = {"verdict": "revise" if str(pk.get("verdict")) == "revise" else "accept", "preferred_id": chosen["id"],
                      "issues": _tools_clip_list(pk.get("issues"), 6, 160), "fixes": _tools_clip_list(pk.get("fixes"), 6, 160)}
            meter.flush("plan:critic")
            yield stage("critic", "done", critic=critic)

            # 7) চূড়ান্ত প্ল্যান (শক্তিশালী)
            if not _tools_balance_ok(uid):
                yield fail("Tokens are used up. Watch an ad to get more tokens.", "TOKEN_LIMIT")
                return
            yield stage("final", "running")
            final_data = (f"ENVIRONMENT FACTS: {_TOOLS_ENV_FACTS}\nNOW_EPOCH: {int(time.time())}\nGOAL: {goal}\nCONSTRAINTS: {cons_line}\n"
                          f"DEVICE: {device or '{}'}\nHINTS: {hints or '-'}\n"
                          f"CHOSEN: {chosen['id']} | {chosen['name']} | {chosen['summary']}\nOUTLINE: {' > '.join(chosen['outline'])}\n"
                          f"ASSUMPTIONS: {'; '.join(chosen['assumptions']) or '-'}\nREVIEWER FIXES: {'; '.join(critic['fixes']) or '-'}\n"
                          f"EVIDENCE FAILURES: {'; '.join(evidence[chosen['id']]['failures']) or '-'}\n"
                          f"OTHER CANDIDATES: {'; '.join(c['id'] + ' ' + c['name'] for c in ranked if c['id'] != chosen['id'])}")
            steps, notes, fj = [], [], {}
            for attempt in range(2):
                prompt = final_data if attempt == 0 else final_data + "\nPREVIOUS ANSWER HAD NO VALID STEPS. Problems: " + "; ".join(notes[:6] or ["empty steps"])
                r = yield from _tools_wait(_tools_submit(_tools_llm, "final", TOOLS_FINAL_INSTRUCTIONS, prompt, False, 90))
                meter.add(r)
                fj = _tools_json(r["text"])
                steps, notes = _tools_sanitize_steps(fj.get("steps"), _TOOLS_MAX_PLAN_STEPS)
                if steps:
                    break
            meter.flush("plan:final")
            if not steps:
                yield fail("Could not build a valid plan — try again.")
                return
            why_not = {}
            if isinstance(fj.get("alternatives"), list):
                for a in fj["alternatives"][:8]:
                    if isinstance(a, dict) and a.get("id") is not None:
                        why_not[str(a["id"])] = _tools_clip(a.get("why_not"), 120)
            alternatives = [{"id": c["id"], "name": c["name"], "summary": c["summary"], "score": c["total"],
                             "why_not": why_not.get(c["id"], "")} for c in ranked if c["id"] != chosen["id"]][:4]
            result = {"plan": {"steps": steps, "pipeline": {"id": chosen["id"], "name": chosen["name"], "summary": chosen["summary"]}},
                      "alternatives": alternatives, "rationale": _tools_clip(fj.get("rationale"), 800),
                      "estimate": _tools_estimate(fj.get("estimate")), "warnings": warnings + notes[:6]}
            yield stage("final", "done", step_count=len(steps))
            yield sse("done", result=result, session_id=sid)
        except GeneratorExit:
            raise
        except AIProviderError as e:
            yield fail(_tools_clip(str(e), 200), "AI_ERROR")
        except Exception as e:
            print(f"[tools] plan crashed: {_redact_secrets(str(e))[:200]}")
            yield fail("Unexpected error while planning.", "SERVER_ERROR")
        finally:
            meter.flush("plan:partial")   # ক্লায়েন্ট কেটে গেলেও এ পর্যন্ত খরচ কাটা

    return make_sse_response(gen())


# ============================ POST /api/tools/decide ============================
@app.route("/api/tools/decide", methods=["POST"])
@require_session
def tools_decide():
    """
    Body: {goal, plan_position{index,total}, remaining_steps[], context_history[], last_result, workspace_states{},
           vault_titles[], permission_states{}, user_note?, failure_history[], session_id?}
    Response: {note, status, say, steps[], wait_until?, ask_user?, edit_goal?, done, rejected[], tokens}
    """
    body = request.get_json(silent=True) or {}
    goal = _tools_clip(body.get("goal"), 600)
    if not goal:
        return jsonify({"error": "goal is required"}), 400
    uid = g.uid
    gate = _tools_gate(uid, "decide")
    if gate:
        return gate
    pos = body.get("plan_position") if isinstance(body.get("plan_position"), dict) else {}

    def _int(v, hi=10000):
        try:
            return max(0, min(hi, int(float(v))))
        except (TypeError, ValueError):
            return 0
    history = _tools_clip_list(body.get("context_history"), 12, 200)
    last_result = _tools_clip(body.get("last_result"), 1500)      # মাস্ক আগে, ছাঁটা পরে (_tools_clip-এর নিয়ম)
    states = body.get("workspace_states") if isinstance(body.get("workspace_states"), dict) else {}
    state_line = " ".join(f"{k}={_tools_clip(states.get(k), 120) or '-'}" for k in _TOOLS_STATE_KEYS)
    titles, seen = [], set()
    if isinstance(body.get("vault_titles"), list):
        for t in body["vault_titles"]:
            if isinstance(t, str):
                tt = _tools_clip(t, 60)
                if tt and tt not in seen:
                    seen.add(tt)
                    titles.append(tt)
            if len(titles) >= 40:
                break
    perms = body.get("permission_states") if isinstance(body.get("permission_states"), dict) else {}
    perm_items = []
    for k, v in list(perms.items())[:16]:
        key = re.sub(r"[^a-z0-9_]", "", str(k).lower())[:32]
        if key:
            perm_items.append(f"{key}={_tools_clip(v, 20)}")
    user_note = _tools_clip(body.get("user_note"), 500)
    failures = _tools_clip_list(body.get("failure_history"), 6, 200)
    remaining = _tools_compact_steps(body.get("remaining_steps"), 8)
    now = int(time.time())
    prompt = (f"ENVIRONMENT FACTS: {_TOOLS_ENV_FACTS}\nNOW_EPOCH: {now}\nGOAL: {goal}\n"
              f"POSITION: step {_int(pos.get('index'))} of {_int(pos.get('total'))}\n"
              f"REMAINING:\n{chr(10).join(remaining) or '-'}\nHISTORY:\n{chr(10).join(history) or '-'}\n"
              f"LAST_RESULT: {last_result or '-'}\nWORKSPACES: {state_line}\n"
              f"VAULT_TITLES: {' | '.join(titles) or '-'}\nPERMISSIONS: {' '.join(perm_items) or '-'}\n"
              f"USER_NOTE: {user_note or '-'}\nFAILURE_HISTORY:\n{chr(10).join(failures) or '-'}")
    meter = _ToolsMeter(uid)
    parsed, last_err = {}, None
    for attempt in range(2):
        p = prompt if attempt == 0 else prompt + "\nYOUR PREVIOUS ANSWER WAS NOT VALID JSON. Reply with the JSON object only."
        stage_name = "decide" if attempt == 0 else "final"        # ২য় চেষ্টা শক্তিশালী মডেলে
        try:
            r = _tools_llm(stage_name, TOOLS_DECIDE_INSTRUCTIONS, p, timeout=45)
        except AIProviderError as e:
            last_err = e
            break
        meter.add(r)
        parsed = _tools_json(r["text"])
        if parsed:
            break
    tin, tout = meter.flush("decide")
    if not parsed:
        return jsonify({"error": _tools_clip(str(last_err), 200) if last_err else "Could not understand the AI's answer — try again.",
                        "tokens": tin + tout}), 502
    clean, rejected = sanitize_tools_decide_response(parsed, vault_titles=titles, now=now)
    clean["rejected"] = rejected[:10]
    clean["tokens"] = tin + tout
    sid = _tools_session_id(body)
    if sid:
        clean["session_id"] = sid
    return jsonify(clean)


# ============================ POST /api/tools/learn ============================
_TOOLS_LEARN_LOCK = threading.Lock()
_TOOLS_OUTCOMES = ("success", "failure", "partial")
_TOOLS_VERIFY_AFTER = 2          # স্পেক: দুইবার সফল হলে তবেই verified


def _tools_num(v, hi):
    try:
        f = float(v)
        return max(0.0, min(hi, f)) if f == f else 0.0
    except (TypeError, ValueError):
        return 0.0


@app.route("/api/tools/learn", methods=["POST"])
@require_session
def tools_learn():
    """
    Body: {goal_summary, pipeline_used{name?, steps[{workspace,action}]}|str, outcome: success|failure|partial,
           metrics{time_s,cost,retries}, failure_reasons[], pipeline_id?, session_id?}
    Response: {ok, note_id, verified, successes, failures}. LLM নেই → টোকেন কাটা নেই (আউটপুট না হারানোর জন্য টোকেন-গেটও নেই)।
    """
    body = request.get_json(silent=True) or {}
    uid = g.uid
    gate = _tools_gate(uid, "learn", need_tokens=False)
    if gate:
        return gate
    outcome = str(body.get("outcome") or "").strip().lower()
    if outcome not in _TOOLS_OUTCOMES:
        return jsonify({"error": "outcome must be success, failure or partial"}), 400
    goal_sum = _tools_scrub_pii(_tools_clip(body.get("goal_summary"), 300))
    if not goal_sum:
        return jsonify({"error": "goal_summary is required"}), 400
    pu = body.get("pipeline_used")
    name, sig_parts = "", []
    if isinstance(pu, dict):
        name = _tools_scrub_pii(_tools_clip(pu.get("name"), 100))
        for s in (pu.get("steps") if isinstance(pu.get("steps"), list) else [])[:40]:
            if isinstance(s, dict):
                ws, act = _tools_clip(s.get("workspace"), 12).lower(), _tools_clip(s.get("action"), 20).lower()
                if ws in _TOOLS_WORKSPACES and act in _TOOLS_ACTIONS[ws]:
                    sig_parts.append(f"{ws}.{act}")
    elif isinstance(pu, str):
        name = _tools_scrub_pii(_tools_clip(pu, 100))
    if not name and not sig_parts:
        return jsonify({"error": "pipeline_used is required"}), 400
    sig = "|".join(sig_parts)
    pid = re.sub(r"[^a-z0-9_\-]", "", str(body.get("pipeline_id") or "").lower())[:40]
    key = pid if len(pid) >= 6 else hashlib.sha1(f"{name.lower()}#{sig}".encode("utf-8")).hexdigest()[:12]
    note_id = "pl_" + key
    m = body.get("metrics") if isinstance(body.get("metrics"), dict) else {}
    t_s, cost, retries = _tools_num(m.get("time_s"), 1e7), _tools_num(m.get("cost"), 1e6), _tools_num(m.get("retries"), 1000)
    reasons = [_tools_scrub_pii(r) for r in _tools_clip_list(body.get("failure_reasons"), 5, 160)]

    with _TOOLS_LEARN_LOCK:
        old = get_rag_note(note_id, kind="pipelines") or {}
        succ = int(old.get("successes") or 0) + (1 if outcome == "success" else 0)
        fail_n = int(old.get("failures") or 0) + (1 if outcome == "failure" else 0)
        runs = int(old.get("runs") or 0) + 1
        verified = bool(old.get("verified")) or succ >= _TOOLS_VERIFY_AFTER
        time_total = float(old.get("time_total") or 0) + t_s
        cost_total = float(old.get("cost_total") or 0) + cost
        retries_total = float(old.get("retries_total") or 0) + retries
        recent = list(old.get("recent_failures") or [])
        for r in reasons:
            if r and r not in recent:
                recent.append(r)
        recent = recent[-5:]
        goal_kept = old.get("goal_summary") or goal_sum
        content = (f"Goal: {goal_kept}\nSteps: {' > '.join(sig_parts)[:900] or '-'}\n"
                   f"Status: {'verified' if verified else 'unverified'}; successes={succ}; failures={fail_n}; runs={runs}\n"
                   f"Average: time_s={round(time_total / runs)}; cost={round(cost_total / runs, 4)}; retries={round(retries_total / runs, 2)}\n"
                   f"Recent failure reasons: {'; '.join(recent) or '-'}")
        keywords = " ".join(dict.fromkeys(re.findall(r"\w{3,}", f"{goal_kept} {name}".lower())))[:300]
        saved = save_rag_note(note_id, name or goal_kept[:80], content, keywords, kind="pipelines")
        extra = {"verified": verified, "successes": succ, "failures": fail_n, "runs": runs, "time_total": time_total,
                 "cost_total": cost_total, "retries_total": retries_total, "recent_failures": recent, "goal_summary": goal_kept}
        if _db is not None:
            try:
                _rag_notes_collection("pipelines").document(note_id).set(extra, merge=True)
            except Exception as e:
                print(f"[WARN] tools learn extra-fields save failed: {_redact_secrets(str(e))[:120]}")
        with _rag_notes_cache_lock:
            saved.update(extra)          # save_rag_note ক্যাশে যে dict বসিয়েছে সেটাই — একই অবজেক্ট
    return jsonify({"ok": True, "note_id": note_id, "verified": verified, "successes": succ, "failures": fail_n})
