_AUTO_THUMB_MAX_BYTES = 3_000_000


def _auto_sniff_image(data):
    """ছবির ম্যাজিক-বাইট দেখে MIME; ছবি না হলে None (SVG/HTML আপলোড ঠেকাতে শুধু PNG/JPEG/WebP)।"""
    if data[:8] == b"\x89PNG\r\n\x1a\n":
        return "image/png"
    if data[:3] == b"\xff\xd8\xff":
        return "image/jpeg"
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return "image/webp"
    return None


def _auto_prepare_thumb(data):
    """আপলোড-করা ছবি → (bytes, mime)। Pillow থাকলে সর্বোচ্চ ১০৮০px প্রস্থে ছোট করে JPEG/PNG; না থাকলে যেমন আছে।"""
    mime = _auto_sniff_image(data)
    if not mime:
        raise ValueError("The image must be PNG / JPG / WebP.")
    try:
        from PIL import Image
        import io as _io
        im = Image.open(_io.BytesIO(data))
        im.load()
        if im.width > 1080:
            im = im.resize((1080, max(1, round(im.height * 1080 / im.width))), Image.LANCZOS)
        out = _io.BytesIO()
        if im.mode in ("RGBA", "LA", "P") and mime == "image/png":
            im.convert("RGBA").save(out, "PNG", optimize=True)
            return out.getvalue(), "image/png"
        im.convert("RGB").save(out, "JPEG", quality=86, optimize=True)
        return out.getvalue(), "image/jpeg"
    except ImportError:
        return data, mime
    except Exception:
        raise ValueError("The image could not be read — try another image.")


def _auto_read_blob(blob_id):
    ref = get_db().collection("automation_blobs").document(blob_id)
    meta = ref.get()
    if not meta.exists:
        return None, None
    m = meta.to_dict()
    chunks = [c.to_dict()["data"] for c in ref.collection("chunks").order_by("__name__").stream()]
    data = b"".join(bytes(c) for c in chunks)
    if len(data) != m.get("size"):
        return None, None
    return data, m


def _auto_thumb_response(agent_id, public):
    try:
        snap = _auto_agent_ref(agent_id).get()
        if not snap.exists:
            return jsonify({"error": "not found"}), 404
        d = snap.to_dict()
        if public and not d.get("enabled", True):
            return jsonify({"error": "not found"}), 404
        bid = d.get("thumb_blob_id")
        if not bid or not re.match(r"^[a-f0-9]{32}$", bid):
            return jsonify({"error": "no thumbnail"}), 404
        data, _m = _auto_read_blob(bid)
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    if not data:
        return jsonify({"error": "no thumbnail"}), 404
    return Response(data, mimetype=d.get("thumb_mime") or "image/jpeg",
                    headers={"Content-Length": str(len(data)),
                             "Cache-Control": "private, max-age=86400",
                             "X-Content-Type-Options": "nosniff"})


@app.route("/api/automation/thumb/<agent_id>", methods=["GET"])
@require_session
def automation_thumb(agent_id):
    """এজেন্ট কার্ডের থাম্বনেইল (ফাইভার-গিগের মতো কভার ছবি) — অ্যাডমিন প্যানেল থেকে আপলোড।"""
    return _auto_thumb_response(agent_id, public=True)


@app.route("/api/automation/blob/<blob_id>", methods=["GET"])
@require_session
def automation_blob(blob_id):
    if not re.match(r"^[a-f0-9]{32}$", blob_id):
        return jsonify({"error": "bad id"}), 400
    try:
        ref = get_db().collection("automation_blobs").document(blob_id)
        meta = ref.get()
        if not meta.exists:
            return jsonify({"error": "not found"}), 404
        m = meta.to_dict()
        chunks = [c.to_dict()["data"] for c in ref.collection("chunks").order_by("__name__").stream()]
    except Exception as e:
        return jsonify({"error": str(e)}), 502
    data = b"".join(bytes(c) for c in chunks)
    if len(data) != m.get("size"):
        return jsonify({"error": "blob incomplete"}), 502
    return Response(data, mimetype="application/octet-stream",
                    headers={"Content-Length": str(len(data)), "X-LP-SHA256": m.get("sha256", "")})


def _auto_store_blob(filename, data):
    blob_id = uuid.uuid4().hex
    ref = get_db().collection("automation_blobs").document(blob_id)
    n = 0
    for i in range(0, len(data), _AUTO_BLOB_CHUNK):
        ref.collection("chunks").document("%04d" % n).set({"data": data[i:i + _AUTO_BLOB_CHUNK]})
        n += 1
    sha = hashlib.sha256(data).hexdigest()
    ref.set({"name": filename, "size": len(data), "sha256": sha, "n": n,
             "created_at": dt.datetime.utcnow().isoformat()})
    return blob_id, sha


def _auto_delete_blob(blob_id):
    try:
        ref = get_db().collection("automation_blobs").document(blob_id)
        for c in ref.collection("chunks").stream():
            c.reference.delete()
        ref.delete()
    except Exception as e:
        print(f"[WARN] blob delete failed: {e}")


